// spec: .qa/e2e/specs/moderation-menu.md 1.2 · seed: tests/seed.user4.moderation.spec.ts · тикеты #714b7a (AC 4, 8; реджект r8 — окна сообщений), #4d3a4c (AC 4, 9)
// @data: user4 пишет «QA-AUTO …» в общий чат (/community-chat) и удаляет его (в finally — запасное удаление по id).
import { test, expect } from '@playwright/test';
import { tapIn, appApi, closeApp, deleteCommunity, iphoneAs, qaText } from './mod-helpers';
import type { Api } from '../_shared/api';

test.describe('רכיב תפריט דיווח וחסימה — свой контент', () => {
  test('Своё сообщение в общем чате: «פעולות על ההודעה» → «מחיקת ההודעה»; окно «למחוק את ההודעה?»; «ביטול» — остаётся, «מחיקה» — удалено @iphone @data (#714b7a #4d3a4c)', async ({ browser }) => {
    test.setTimeout(120_000);
    const page = await iphoneAs(browser, 'user4');
    const text = qaText('714b7a', 'community');
    let api: Api | undefined;
    let id = '';
    try {
      api = await appApi(page);
      await page.goto('/community-chat');
      const box = page.getByRole('textbox', { name: 'הודעה לקהילה' });
      await expect(box).toBeVisible();

      // Отправка через UI
      await box.fill(text);
      const sent = page.waitForResponse((r) => r.request().method() === 'POST' && r.url().includes('/rest/v1/community_messages'));
      await tapIn(page, page.getByRole('button', { name: 'שליחה' }));
      const res = await sent;
      expect(res.status(), 'POST community_messages').toBe(201);
      id = String((await res.json()).id ?? '');
      const msg = page.getByRole('button', { name: text, exact: true });
      await expect(msg).toBeVisible();

      // Меню своего сообщения: только удаление
      await tapIn(page, msg);
      const menu = page.getByRole('dialog').filter({ hasText: 'פעולות על ההודעה' });
      await expect(menu.getByRole('button', { name: /מחיקת ההודעה/ })).toBeVisible();
      await expect(menu.getByRole('button', { name: /דיווח/ })).toHaveCount(0);
      await expect(menu.getByRole('button', { name: /חסימ/ })).toHaveCount(0);

      // Окно подтверждения
      await tapIn(page, menu.getByRole('button', { name: /מחיקת ההודעה/ }));
      const confirm = page.getByRole('dialog').filter({ hasText: 'למחוק את ההודעה?' });
      await expect(confirm).toContainText('אי אפשר לשחזר אחרי מחיקה');
      await tapIn(page, confirm.getByRole('button', { name: 'ביטול', exact: true }));
      await expect(confirm).toHaveCount(0);
      await expect(msg).toBeVisible();

      // Удаление
      await tapIn(page, msg);
      await tapIn(page, page.getByRole('button', { name: /מחיקת ההודעה/ }));
      const del = page.waitForResponse((r) => r.request().method() === 'DELETE' && r.url().includes('/rest/v1/community_messages?id=eq.'));
      await tapIn(page, page.getByRole('dialog').filter({ hasText: 'למחוק את ההודעה?' }).getByRole('button', { name: 'מחיקה', exact: true }));
      expect((await del).ok(), 'DELETE community_messages').toBeTruthy();
      await expect(msg).toHaveCount(0);
      id = '';
    } finally {
      if (api && id) await deleteCommunity(api, [id]);
      await closeApp(page, 'user4');
    }
  });
});
